/** Disciplinary cases (confidential) — GET /api/v1/personnel/disciplinary-cases (who may call: holders of personnel.discipline.manage). */
export function listCasesPersonnelDisciplinary(query?: { employee_id?: number | null; status?: "Open" | "Decided" | "Dropped" | null }): Promise<DisciplinaryCaseOut[]> {
  return api<DisciplinaryCaseOut[]>("GET", withQuery(`/personnel/disciplinary-cases`, query), undefined);
}

/** Open a disciplinary case — POST /api/v1/personnel/employees/{employee_id}/disciplinary-cases (who may call: holders of personnel.discipline.manage). */
export function openCasePersonnelEmployeesDisciplinaryCases(employee_id: number, body: DisciplinaryCaseIn): Promise<DisciplinaryCaseOut> {
  return api<DisciplinaryCaseOut>("POST", `/personnel/employees/${employee_id}/disciplinary-cases`, body, { idempotent: true });
}

/** Decide or drop a case — POST /api/v1/personnel/disciplinary-cases/{case_id}/decide (who may call: holders of personnel.discipline.manage). */
export function decideCasePersonnelDisciplinaryCases(case_id: number, body: DisciplinaryDecisionIn): Promise<DisciplinaryCaseOut> {
  return api<DisciplinaryCaseOut>("POST", `/personnel/disciplinary-cases/${case_id}/decide`, body, { idempotent: true });
}

